import{c as r,Q as t,j as a,m as i}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"Bridging Requirements and Architecture: Multi-Agent Orchestration with External Knowledge and Hierarchical Memory","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.01385","title":"Bridging Requirements and Architecture: Multi-Agent Orchestration with External Knowledge and Hierarchical Memory","arxiv_id":2606.01385,"collected_at":"2026-08-04T00:00:00.000Z","collected_by":"routine-d","domain":"Multi-Agent","pdf_path":"pdfs/2606.01385.pdf","year":2026},"headers":[],"relativePath":"research/papers/2026-08-04-maad-bridging-requirements-architecture-multi-agent-orchestration-2606-01385.md","filePath":"research/papers/2026-08-04-maad-bridging-requirements-architecture-multi-agent-orchestration-2606-01385.md","lastUpdated":1785909234000}'),n={name:"research/papers/2026-08-04-maad-bridging-requirements-architecture-multi-agent-orchestration-2606-01385.md"};function c(d,e,o,s,l,h){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="bridging-requirements-and-architecture-multi-agent-orchestration-with-external-knowledge-and-hierarchical-memory" tabindex="-1">Bridging Requirements and Architecture: Multi-Agent Orchestration with External Knowledge and Hierarchical Memory <a class="header-anchor" href="#bridging-requirements-and-architecture-multi-agent-orchestration-with-external-knowledge-and-hierarchical-memory" aria-label="Permalink to &quot;Bridging Requirements and Architecture: Multi-Agent Orchestration with External Knowledge and Hierarchical Memory&quot;">​</a></h1><h2 id="摘要-核心貢獻" tabindex="-1">摘要 / 核心貢獻 <a class="header-anchor" href="#摘要-核心貢獻" aria-label="Permalink to &quot;摘要 / 核心貢獻&quot;">​</a></h2><p>論文提出 MAAD 框架，用於自動化軟體架構設計：協調四個專職 agent（Analyst、Modeler、Designer、Evaluator）自主協作，將需求規格轉換為完整、多視角的架構藍圖。框架整合 RAG 以納入架構標準，並實作階層式記憶支援迭代改善。與 MetaGPT 對比測試顯示 MAAD 產生的架構更模組化、更可追溯。作者指出產出架構品質高度依賴底層 LLM 的推理能力，使用如 GPT-5.2 等進階模型時各項評測指標表現更優。</p><h2 id="與-harness-的關聯" tabindex="-1">與 Harness 的關聯 <a class="header-anchor" href="#與-harness-的關聯" aria-label="Permalink to &quot;與 Harness 的關聯&quot;">​</a></h2><p>四專職 agent 分工（分析→建模→設計→評估）+ 階層式記憶迭代改善的模式，可作為 fusion lead/sidekick 架構或多階段 code review pipeline（發現→驗證→綜合）設計時，「角色分工如何配 external knowledge 與記憶」的具體案例參照。</p>',5)])])}const m=r(n,[["render",c]]);export{g as __pageData,m as default};
